const rows = $input.all().map(i => i.json);
const good = rows.filter(r => r.found !== false && r.valid !== false);
const bad = rows.filter(r => r.found === false || r.valid === false);
const f = (v, d = 1) => (v === null || v === undefined ? '-' : Number(v).toFixed(d));

const lines = [
  'Rank  Symbol   Price   Chg%   RSI   52w%  Upside%',
  ...good.map(r => [
    String(r.rank ?? '-').padEnd(5),
    String(r.symbol).padEnd(8),
    f(r.price, 2).padStart(7),
    f(r.change_pct, 2).padStart(6),
    f(r.rsi, 0).padStart(5),
    f(r.week52_position_pct, 0).padStart(6),
    f(r.analyst_upside_pct, 1).padStart(8),
  ].join(' ')),
];
if (bad.length) lines.push('', 'Not compared: ' + bad.map(r => `${r.symbol} (${r.error})`).join('; '));

return [{ json: { table: lines.join('\n') } }];
